/* ============================================================
   PRODUCT LIST
============================================================ */
export function ProductListPage() {
    const [page, setPage] = useState(1);
    const [perPage, setPerPage] = useState(CRM_DEFAULT_PER_PAGE);
    const [search, setSearch] = useState("");
    const [categoryFilter, setCategoryFilter] = useState("");
    const [showForm, setShowForm] = useState(false);
    const [editProduct, setEditProduct] = useState<Product | null>(null);
    const [showCategoryPage, setShowCategoryPage] = useState(false);
    const [detailProductId, setDetailProductId] = useState<number | null>(null);
    const { data: categories = [] } = useProductCategoryList();
    const { data: productPage, isLoading } = usePaginatedProductList({
        page,
        per_page: perPage,
        search: search || undefined,
        category_id: categoryFilter ? Number(categoryFilter) : undefined,
    });
    const products = productPage?.data ?? [];
    const deleteMutation = useDeleteProduct();
    if (detailProductId !== null) return <ProductDetailView id={detailProductId} onClose={() => setDetailProductId(null)}/>;
    if (showCategoryPage) return <CategoryPage onClose={() => setShowCategoryPage(false)}/>;
    if (showForm && !editProduct) {
        return (<ProductFormModal product={null} categories={categories} onClose={() => {
                setShowForm(false);
                setEditProduct(null);
            }}/>);
    }
    async function handleDelete(p: Product) {
        if (!confirm(`Hapus produk "${p.name}"?`)) {
            return;
        }
        try {
            await deleteMutation.mutateAsync(p.id);
        }
        catch (err) {
            alert(extractErrorMessage(err));
        }
    }
    return (
      <div className="crm-product-ui">
        <ProductPageStyles />
        <PageHeader
          title="Produk & Jasa"
          subtitle="Master data produk dan layanan MSDC."
          containerClassName="px-7 pt-5 pb-2"
        />
        <main className="crm-product-content">
          <section className="crm-product-overview" aria-label="Ringkasan produk dan jasa">
            <article className="crm-product-metric">
              <span className="crm-product-metric__icon crm-product-metric__icon--blue" aria-hidden="true">
                <Package size={20} strokeWidth={2.1} />
              </span>
              <div className="crm-product-metric__copy">
                <span className="crm-product-metric__label">Total Produk &amp; Jasa</span>
                <strong className="crm-product-metric__value">{productPage?.total ?? 0}</strong>
                <span className="crm-product-metric__note">Data sesuai pencarian dan kategori</span>
              </div>
            </article>
            <article className="crm-product-metric">
              <span className="crm-product-metric__icon crm-product-metric__icon--amber" aria-hidden="true">
                <Tags size={20} strokeWidth={2.1} />
              </span>
              <div className="crm-product-metric__copy">
                <span className="crm-product-metric__label">Kategori Tersedia</span>
                <strong className="crm-product-metric__value">{categories.length}</strong>
                <span className="crm-product-metric__note">Kategori produk dan layanan</span>
              </div>
            </article>
            <article className="crm-product-metric">
              <span className="crm-product-metric__icon crm-product-metric__icon--violet" aria-hidden="true">
                <ClipboardList size={20} strokeWidth={2.1} />
              </span>
              <div className="crm-product-metric__copy">
                <span className="crm-product-metric__label">Ditampilkan</span>
                <strong className="crm-product-metric__value">{products.length}</strong>
                <span className="crm-product-metric__note">Produk pada halaman ini</span>
              </div>
            </article>
          </section>

          <section className="crm-product-list-card" aria-label="Daftar produk dan jasa">
            <div className="crm-product-list-heading">
              <div>
                <h2 className="crm-product-list-heading__title">Daftar Produk &amp; Jasa</h2>
                <p className="crm-product-list-heading__subtitle">
                  Kelola katalog layanan, kategori, satuan, dan harga dasar MSDC.
                </p>
              </div>
              <span className="crm-product-list-heading__meta">
                <Package size={13} strokeWidth={2.1} />
                {productPage?.total ?? 0} Produk
              </span>
            </div>

            <div className="crm-product-toolbar">
              <label className="crm-product-search">
                <Search size={16} strokeWidth={2} aria-hidden="true" />
                <input
                  type="text"
                  aria-label="Cari produk"
                  value={search}
                  placeholder="Cari nama atau kode produk..."
                  onChange={(e) => { setSearch(e.target.value); setPage(1); }}
                />
              </label>

              <label className="crm-product-filter-wrap">
                <Tag size={14} aria-hidden="true" />
                <select
                  className="crm-product-filter"
                  aria-label="Filter kategori produk"
                  value={categoryFilter}
                  onChange={(e) => { setCategoryFilter(e.target.value); setPage(1); }}
                >
                  <option value="">Semua Kategori</option>
                  {categories.map((category) => (
                    <option key={category.id} value={category.id}>{category.name}</option>
                  ))}
                </select>
              </label>

              <button type="button" onClick={() => setShowCategoryPage(true)} className="crm-product-toolbar-button">
                <Tag size={15} strokeWidth={2.2} />
                Kategori
              </button>

              <button
                type="button"
                onClick={() => { setEditProduct(null); setShowForm(true); }}
                className="crm-product-toolbar-button crm-product-toolbar-button--primary"
              >
                <Plus size={16} strokeWidth={2.5} />
                Produk Baru
              </button>
            </div>

            {isLoading && <div className="crm-product-empty"><LoadingState /></div>}

            {!isLoading && products.length === 0 && (
              <div className="crm-product-empty">
                <EmptyState title="Belum Ada Produk" subtitle="Produk dan jasa MSDC akan muncul di sini." />
              </div>
            )}

            {products.length > 0 && (
              <div className="crm-product-table-wrap">
                <table className="crm-product-table">
                  <thead>
                    <tr>
                      <th>Kode</th>
                      <th>Nama</th>
                      <th>Kategori</th>
                      <th>Tipe Layanan</th>
                      <th>Harga Dasar</th>
                      <th>Aksi</th>
                    </tr>
                  </thead>
                  <tbody>
                    {products.map((p) => {
                      const hasResourceTemplate = !!(
                        p.default_rack_u ||
                        p.default_rack_mode === "whole_rack" ||
                        p.default_ip_count ||
                        p.default_power_watt ||
                        p.default_bandwidth_mbps ||
                        p.default_requires_cross_connect
                      );
                      return (
                        <tr key={p.id}>
                          <td><span className="crm-product-code">{p.product_code || "—"}</span></td>
                          <td>
                            <div className="crm-product-name">
                              <span className="crm-product-name__icon" aria-hidden="true"><Package size={16} strokeWidth={2} /></span>
                              <span className="crm-product-name__text">{p.name}</span>
                            </div>
                          </td>
                          <td><span className="crm-product-category-chip">{p.category?.name ?? "—"}</span></td>
                          <td>
                            <span className="crm-product-service-type">
                              <Layers3 size={12} strokeWidth={2.2} />
                              {SERVICE_TYPE_LABELS[p.service_type] ?? p.service_type}
                            </span>
                            {hasResourceTemplate && (
                              <div title="Template resource DataCenterOps - otomatis mengalir ke Sales Order" className="crm-product-resource-note">
                                {p.default_rack_mode === "whole_rack" ? "1 Rack Penuh " : p.default_rack_u ? `${p.default_rack_u}U ` : ""}
                                {p.default_ip_count ? `${p.default_ip_count}IP ` : ""}
                                {p.default_power_watt ? `${p.default_power_watt}W ` : ""}
                                {p.default_bandwidth_mbps ? `${p.default_bandwidth_mbps}Mbps ` : ""}
                                {p.default_requires_cross_connect ? "XC" : ""}
                              </div>
                            )}
                          </td>
                          <td><span className="crm-product-price">{formatCurrency(Number(p.base_price))}</span></td>
                          <td>
                            <div className="crm-product-actions">
                              <button type="button" className="crm-product-action crm-product-action--detail" onClick={() => setDetailProductId(p.id)}>
                                <Eye size={14} /> Detail
                              </button>
                              <button
                                type="button"
                                className="crm-product-action crm-product-action--edit"
                                onClick={() => { setEditProduct(p); setShowForm(true); }}
                              >
                                <Pencil size={13} /> Edit
                              </button>
                              <button type="button" className="crm-product-action crm-product-action--delete" onClick={() => handleDelete(p)}>
                                <Trash2 size={13} /> Hapus
                              </button>
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}

            {productPage && productPage.total > 0 && (
              <CrmPagination
                currentPage={productPage.current_page}
                lastPage={productPage.last_page}
                total={productPage.total}
                perPage={perPage}
                onPageChange={setPage}
                onPerPageChange={setPerPage}
              />
            )}
          </section>

          {showForm && editProduct && (
            <ProductFormModal
              product={editProduct}
              categories={categories}
              onClose={() => { setShowForm(false); setEditProduct(null); }}
            />
          )}
        </main>
      </div>
    );
}
function ProductPhotoLightbox({ src, title, onClose }: { src: string; title: string; onClose: () => void }) {
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [onClose]);

  return createPortal(
    <div className="crm-preview-lightbox-overlay" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}>
      <div className="crm-preview-lightbox" role="dialog" aria-modal="true" aria-label={title}>
        <div className="crm-preview-lightbox-head">
          <strong title={title}>{title}</strong>
          <button type="button" className="crm-preview-lightbox-close" onClick={onClose} aria-label="Tutup foto" title="Tutup foto"><X size={20} /></button>
        </div>
        <div className="crm-preview-lightbox-image"><img src={src} alt={title} /></div>
      </div>
    </div>,
    document.body
  );
}

/* Detail produk sebagai halaman dengan header, termasuk foto tersimpan. */
function ProductDetailView({ id, onClose }: { id: number; onClose: () => void }) {
    const { data: product, isLoading, isError } = useProduct(id);
    const [photoUrl, setPhotoUrl] = useState<string | null>(null);
    const [showPhotoPreview, setShowPhotoPreview] = useState(false);
    useEffect(() => {
        const imageId = product?.image_file_id;
        if (!imageId) { setPhotoUrl(null); return; }
        let cancelled = false;
        let url: string | null = null;
        fileApi.previewBlob(imageId).then(result => {
            url = URL.createObjectURL(result.data);
            if (!cancelled) setPhotoUrl(url);
            else URL.revokeObjectURL(url);
        }).catch(() => { if (!cancelled) setPhotoUrl(null); });
        return () => { cancelled = true; if (url) URL.revokeObjectURL(url); };
    }, [product?.image_file_id]);

    return (
      <div className="crm-product-ui crm-product-detail-page">
        <ProductPageStyles />
        <PageHeader title="Detail Produk & Jasa" subtitle="Informasi layanan, harga, dan foto produk." containerClassName="px-7 pt-5 pb-2" />
        <main className="crm-product-content">
          <div className="crm-product-detail-nav">
            <button type="button" onClick={onClose} className="crm-product-back">
              <ArrowLeft size={16} /> Kembali ke daftar Produk &amp; Jasa
            </button>
            <span className="crm-product-detail-nav__tag">Detail Produk</span>
          </div>
          {isLoading && <LoadingState />}
          {isError && <p role="alert" className="crm-product-form-error">Detail produk gagal dimuat.</p>}
          {product && (
            <section className="crm-product-detail-card">
              <div className="crm-product-detail-heading">
                <div className="crm-product-detail-heading__main">
                  <span className="crm-product-detail-heading__icon" aria-hidden="true"><Package size={22} /></span>
                  <div style={{ minWidth: 0 }}>
                    <p className="crm-product-eyebrow">Informasi produk &amp; jasa</p>
                    <h2 className="crm-product-detail-title">{product.name}</h2>
                    <div className="crm-product-detail-badges">
                      <span className="crm-product-code">{product.product_code || "Kode belum tersedia"}</span>
                      <span className="crm-product-service-type"><Layers3 size={12} />{SERVICE_TYPE_LABELS[product.service_type] ?? product.service_type}</span>
                      <span className={`crm-product-category-chip ${product.is_active ? "crm-product-status--active" : "crm-product-status--inactive"}`}>
                        {product.is_active ? "Aktif" : "Tidak aktif"}
                      </span>
                    </div>
                  </div>
                </div>
              </div>
              <div className="crm-product-detail-grid">
                <div className="crm-product-detail-image">
                  {photoUrl ? (
                    <button type="button" className="crm-preview-photo-button" aria-label={`Lihat foto lengkap ${product.name}`} onClick={() => setShowPhotoPreview(true)}>
                      <img src={photoUrl} alt={`Foto ${product.name}`} />
                      <span className="crm-preview-photo-eye" aria-hidden="true"><span><Eye size={20} /> Lihat foto</span></span>
                    </button>
                  ) : (
                    <div className="crm-product-detail-image__placeholder">
                      <ImageIcon size={34} strokeWidth={1.6} />
                      <span>Belum ada foto produk</span>
                    </div>
                  )}
                </div>
                <div className="crm-product-detail-fields">
                  {([ ["Kode Produk", product.product_code || "—"], ["Kategori", product.category?.name ?? "—"], ["Tipe Layanan", SERVICE_TYPE_LABELS[product.service_type] ?? product.service_type], ["Satuan", product.unit], ["Harga Dasar", formatCurrency(Number(product.base_price))], ["Status", product.is_active ? "Aktif" : "Tidak aktif"] ] as [string, string][]).map(([label, value]) => (
                    <div key={label} className="crm-product-detail-field">
                      <span className="crm-product-detail-field__label">{label}</span>
                      <span className="crm-product-detail-field__value">{value}</span>
                    </div>
                  ))}
                  <div className="crm-product-detail-description">
                    <span className="crm-product-detail-field__label">Deskripsi</span>
                    <div className="crm-product-detail-description__value">{product.description || "—"}</div>
                  </div>
                </div>
              </div>
            </section>
          )}
        </main>
        {showPhotoPreview && photoUrl && product && (
          <ProductPhotoLightbox src={photoUrl} title={`Foto ${product.name}`} onClose={() => setShowPhotoPreview(false)} />
        )}
      </div>
    );
}

/* ============================================================
   CATEGORY PAGE
============================================================ */
function CategoryPage({ onClose, }: {
    onClose: () => void;
}) {
    const qc = useQueryClient();
    const { data: categories = [] } = useProductCategoryList();
    const createMutation = useCreateProductCategory();
    const deleteMutation = useDeleteProductCategory();
    const [name, setName] = useState("");
    const [description, setDescription] = useState("");
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState<string | null>(null);
    async function handleSubmit(e: FormEvent) {
        e.preventDefault();
        if (!name.trim()) {
            setError("Nama kategori wajib diisi.");
            return;
        }
        setError(null);
        setSaving(true);
        try {
            await createMutation.mutateAsync({
                name: name.trim(),
                description: description.trim() ||
                    undefined,
            });
            qc.invalidateQueries({
                queryKey: [
                    "productCategories",
                ],
            });
            qc.invalidateQueries({
                queryKey: ["products"],
            });
            setName("");
            setDescription("");
        }
        catch (err) {
            setError(extractErrorMessage(err));
        }
        finally {
            setSaving(false);
        }
    }
    async function handleDelete(id: number) {
        if (!id || id === 0) {
            alert("ID kategori tidak valid.");
            return;
        }
        if (!confirm("Hapus kategori ini?")) {
            return;
        }
        try {
            await deleteMutation.mutateAsync(id);
            qc.invalidateQueries({
                queryKey: [
                    "productCategories",
                ],
            });
        }
        catch (err) {
            alert(extractErrorMessage(err));
        }
    }
    return (
      <div className="crm-product-ui crm-product-category-page">
        <ProductPageStyles />
        <PageHeader title="Kategori Produk" subtitle="Tambah dan kelola kategori produk & jasa." containerClassName="px-7 pt-5 pb-2" />
        <main className="crm-product-content crm-product-category-content">
          <div className="crm-product-category-nav">
            <button type="button" onClick={onClose} className="crm-product-back">
              <ArrowLeft size={17} aria-hidden="true" /> Kembali ke Produk &amp; Jasa
            </button>
            <span className="crm-product-category-nav__badge">Master Data / Kategori</span>
          </div>
          <div className="crm-product-category-intro">
            <span className="crm-product-category-intro__icon"><Layers3 size={25} aria-hidden="true" /></span>
            <div className="crm-product-category-intro__copy">
              <h2 className="crm-product-category-intro__title">Manajemen Kategori</h2>
              <p className="crm-product-category-intro__subtitle">Susun kategori agar produk dan layanan MSDC lebih mudah dikelola.</p>
            </div>
            <span className="crm-product-category-intro__badge">{categories.length} kategori terdaftar</span>
          </div>
          <div className="crm-product-category-grid">
            <form onSubmit={handleSubmit} className="crm-product-category-card crm-product-category-form">
              <div className="crm-product-card-heading">
                <div className="crm-product-card-heading__main">
                  <span className="crm-product-card-heading__icon"><Tag size={19} /></span>
                  <div>
                    <h2 className="crm-product-card-heading__title">Tambah Kategori</h2>
                    <p className="crm-product-card-heading__subtitle">Buat pengelompokan produk dan layanan.</p>
                  </div>
                </div>
                <span className="crm-product-category-step">01</span>
              </div>
              <div className="crm-product-category-form__fields">
                <div className="crm-product-form-field">
                  <label className="crm-product-form-label" htmlFor="crm-product-category-name">Nama Kategori</label>
                  <input id="crm-product-category-name" className="input" value={name} onChange={(e) => setName(e.target.value)} placeholder="mis. Jasa Setup" />
                </div>
                <div className="crm-product-form-field">
                  <label className="crm-product-form-label" htmlFor="crm-product-category-description">Deskripsi (opsional)</label>
                  <input id="crm-product-category-description" className="input" value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Keterangan singkat..." />
                </div>
                {error && <div className="crm-product-form-error" role="alert">{error}</div>}
                <div className="crm-product-form-actions">
                  <Button type="submit" disabled={saving} className="crm-product-primary-button">
                    <Plus size={16} aria-hidden="true" />{saving ? "Menyimpan..." : "Tambah Kategori"}
                  </Button>
                </div>
              </div>
            </form>

            <section className="crm-product-category-card">
              <div className="crm-product-card-heading">
                <div className="crm-product-card-heading__main">
                  <span className="crm-product-card-heading__icon"><Tags size={19} /></span>
                  <div>
                    <h2 className="crm-product-card-heading__title">Kategori Terdaftar</h2>
                    <p className="crm-product-card-heading__subtitle">Daftar kategori yang tersedia untuk katalog.</p>
                  </div>
                </div>
                <span className="crm-product-category-count">{categories.length} kategori</span>
              </div>
              {categories.length === 0 && (
                <p style={{ margin: 0, padding: "20px 24px 0", color: "#94a3b8", fontSize: 12 }}>Belum ada kategori.</p>
              )}
              <div className="crm-product-category-list">
                {categories.map((category) => (
                  <div key={category.id} className="crm-product-category-item">
                    <span className="crm-product-category-item__icon" aria-hidden="true"><Tag size={17} /></span>
                    <div className="crm-product-category-item__copy">
                      <div className="crm-product-category-item__name">{category.name}</div>
                      {category.description && <div className="crm-product-category-item__description">{category.description}</div>}
                    </div>
                    <button type="button" onClick={() => handleDelete(category.id)} className="crm-product-category-delete">
                      <Trash2 size={13} /> Hapus
                    </button>
                  </div>
                ))}
              </div>
            </section>
          </div>
        </main>
      </div>
    );
}
/* ============================================================
   PRODUCT FORM MODAL
============================================================ */
function ProductFormModal({ product, categories, onClose, }: {
    product: Product | null;
    categories: ProductCategory[];
    onClose: () => void;
}) {
    const qc = useQueryClient();
    const createMutation = useCreateProduct();
    const updateMutation = useUpdateProduct(product?.id ?? 0);
    const [name, setName] = useState(product?.name ?? "");
    const [productCode, setProductCode] = useState(product?.product_code ?? "");
    const [categoryId, setCategoryId] = useState<string>(product?.category_id?.toString() ??
        "");
    const [unit, setUnit] = useState<string>(product?.unit ?? "bulan");
    const [basePrice, setBasePrice] = useState(Number(product?.base_price ?? 0));
    const [costPrice, setCostPrice] = useState(Number(product?.cost_price ?? 0));
    const [description, setDescription] = useState(product?.description ?? "");
    const [imageFileId, setImageFileId] = useState<number | null>(product?.image_file_id ?? null);
    const [serviceType, setServiceType] = useState<string>(product?.service_type ??
        "other");
    const [defaultRackU, setDefaultRackU] = useState(product?.default_rack_u?.toString() ??
        "");
    const [defaultRackMode, setDefaultRackMode,] = useState<"unit" | "whole_rack">(product?.default_rack_mode ??
        "unit");
    const [defaultIpCount, setDefaultIpCount,] = useState(product?.default_ip_count?.toString() ??
        "");
    const [defaultPowerWatt, setDefaultPowerWatt,] = useState(product?.default_power_watt?.toString() ??
        "");
    const [defaultBandwidthMbps, setDefaultBandwidthMbps,] = useState(product?.default_bandwidth_mbps?.toString() ??
        "");
    const [defaultRequiresCrossConnect, setDefaultRequiresCrossConnect,] = useState(product?.default_requires_cross_connect ??
        false);
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const isEdit = !!product;
    async function handleSubmit(e: FormEvent) {
        e.preventDefault();
        if (!name.trim()) {
            setError("Nama produk wajib diisi.");
            return;
        }
        setError(null);
        setSaving(true);
        try {
            const payload = {
                name: name.trim(),
                product_code: productCode.trim() ||
                    undefined,
                category_id: categoryId
                    ? Number(categoryId)
                    : null,
                unit,
                base_price: basePrice,
                cost_price: costPrice,
                description: description.trim() ||
                    undefined,
                image_file_id: imageFileId ??
                    undefined,
                service_type: serviceType,
                default_rack_u: defaultRackU
                    ? Number(defaultRackU)
                    : null,
                default_rack_mode: defaultRackMode,
                default_ip_count: defaultIpCount
                    ? Number(defaultIpCount)
                    : null,
                default_power_watt: defaultPowerWatt
                    ? Number(defaultPowerWatt)
                    : null,
                default_bandwidth_mbps: defaultBandwidthMbps
                    ? Number(defaultBandwidthMbps)
                    : null,
                default_requires_cross_connect: defaultRequiresCrossConnect,
            };
            if (isEdit) {
                await updateMutation.mutateAsync(payload as any);
            }
            else {
                await createMutation.mutateAsync(payload as any);
            }
            qc.invalidateQueries({
                queryKey: ["products"],
            });
            onClose();
        }
        catch (err: unknown) {
            console.error("[ProductForm] submit error:", err);
            const axiosErr = err as {
                response?: {
                    status?: number;
                    data?: unknown;
                };
            };
            const msg = axiosErr?.response?.data
                ? JSON.stringify(axiosErr.response
                    .data)
                : String(err);
            setError("Gagal menyimpan: " +
                msg);
        }
        finally {
            setSaving(false);
        }
    }
    const UNITS = [
        {
            value: "bulan",
            label: "per Bulan",
        },
        {
            value: "unit",
            label: "per Unit",
        },
        {
            value: "project",
            label: "per Project",
        },
        {
            value: "pcs",
            label: "per Pcs",
        },
        {
            value: "jam",
            label: "per Jam",
        },
        {
            value: "lot",
            label: "per Lot",
        },
    ];
    const formContent = (
      <form onSubmit={handleSubmit} className="crm-product-form">
        <section className="crm-product-form-section">
          <div className="crm-product-section-heading">
            <span className="crm-product-section-heading__icon"><Package size={17} /></span>
            <div>
              <h3 className="crm-product-section-heading__title">Informasi Produk</h3>
              <p className="crm-product-section-heading__subtitle">Identitas utama produk atau jasa.</p>
            </div>
            <span className="crm-product-section-heading__step" aria-hidden="true">01</span>
          </div>
          <div className="crm-product-form-field">
            <label className="crm-product-form-label">Nama Produk / Jasa *</label>
            <input className="input" value={name} onChange={(e) => setName(e.target.value)} placeholder="mis. Managed Services — Silver" />
          </div>
          <div className="crm-product-form-grid crm-product-form-grid--two" style={{ marginTop: 14 }}>
            <div className="crm-product-form-field">
              <label className="crm-product-form-label">Kode Produk</label>
              <input className="input" value={productCode} onChange={(e) => setProductCode(e.target.value)} placeholder="AUTO (kosongkan)" />
            </div>
            <div className="crm-product-form-field">
              <label className="crm-product-form-label">Kategori</label>
              <select className="input" value={categoryId} onChange={(e) => setCategoryId(e.target.value)}>
                <option value="">— Pilih —</option>
                {categories.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}
              </select>
            </div>
          </div>
        </section>

        <section className="crm-product-form-section">
          <div className="crm-product-section-heading">
            <span className="crm-product-section-heading__icon" style={{ background: "#fffbeb", color: "#d97706" }}><CircleDollarSign size={17} /></span>
            <div>
              <h3 className="crm-product-section-heading__title">Harga &amp; Deskripsi</h3>
              <p className="crm-product-section-heading__subtitle">Atur satuan penjualan, harga, dan informasi produk.</p>
            </div>
            <span className="crm-product-section-heading__step" aria-hidden="true">02</span>
          </div>
          <div className="crm-product-form-grid crm-product-form-grid--three">
            <div className="crm-product-form-field">
              <label className="crm-product-form-label">Unit</label>
              <select className="input" value={unit} onChange={(e) => setUnit(e.target.value)}>
                {UNITS.map((u) => <option key={u.value} value={u.value}>{u.label}</option>)}
              </select>
            </div>
            <div className="crm-product-form-field crm-product-currency-field">
              <label className="crm-product-form-label">Harga Dasar</label>
              <CurrencyInput value={basePrice} onChange={setBasePrice} />
            </div>
            <div className="crm-product-form-field crm-product-currency-field">
              <label className="crm-product-form-label">Harga Pokok</label>
              <CurrencyInput value={costPrice} onChange={setCostPrice} />
            </div>
          </div>
          <div className="crm-product-form-field" style={{ marginTop: 14 }}>
            <label className="crm-product-form-label">Deskripsi</label>
            <textarea className="input crm-product-form-description" rows={3} value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Detail produk atau layanan..." />
          </div>
        </section>

        <section className="crm-product-form-section">
          <div className="crm-product-section-heading">
            <span className="crm-product-section-heading__icon" style={{ background: "#f5f3ff", color: "#7c3aed" }}><Server size={17} /></span>
            <div>
              <h3 className="crm-product-section-heading__title">Tautan Data Center Ops</h3>
              <p className="crm-product-section-heading__subtitle">Template resource yang dapat diteruskan ke kebutuhan Sales Order.</p>
            </div>
            <span className="crm-product-section-heading__step" aria-hidden="true">03</span>
          </div>
          <div className="crm-product-form-field" style={{ marginBottom: 14 }}>
            <label className="crm-product-form-label">Tipe Layanan</label>
            <select className="input" value={serviceType} onChange={(e) => setServiceType(e.target.value)}>
              {Object.entries(SERVICE_TYPE_LABELS).map(([value, label]) => <option key={value} value={value}>{label}</option>)}
            </select>
          </div>
          <div className="crm-product-form-help">
            <Info size={15} />
            <span>Kebutuhan resource default (opsional) akan otomatis dipakai untuk mengisi kebutuhan Sales Order saat produk ini dipilih di Quotation.</span>
          </div>
          <div className="crm-product-form-grid crm-product-form-grid--resource">
            <div className="crm-product-form-field">
              <label className="crm-product-form-label">Rack (U)</label>
              <input className="input" type="number" min={0} value={defaultRackU} onChange={(e) => setDefaultRackU(e.target.value)} placeholder="0" disabled={defaultRackMode === "whole_rack"} />
              <select className="input" value={defaultRackMode} onChange={(e) => setDefaultRackMode(e.target.value as "unit" | "whole_rack")} title="Ecer = pesan per-U, nyempil bareng tenant lain di 1 rack. 1 Rack = borong 1 rack utuh, eksklusif." style={{ marginTop: 7 }}>
                <option value="unit">Ecer (per-U)</option>
                <option value="whole_rack">1 Rack Penuh</option>
              </select>
            </div>
            <div className="crm-product-form-field">
              <label className="crm-product-form-label">IP</label>
              <input className="input" type="number" min={0} value={defaultIpCount} onChange={(e) => setDefaultIpCount(e.target.value)} placeholder="0" />
            </div>
            <div className="crm-product-form-field">
              <label className="crm-product-form-label">Listrik (W)</label>
              <input className="input" type="number" min={0} value={defaultPowerWatt} onChange={(e) => setDefaultPowerWatt(e.target.value)} placeholder="0" />
            </div>
            <div className="crm-product-form-field">
              <label className="crm-product-form-label">Bandwidth (Mbps)</label>
              <input className="input" type="number" min={0} value={defaultBandwidthMbps} onChange={(e) => setDefaultBandwidthMbps(e.target.value)} placeholder="0" />
            </div>
          </div>
          <label className="crm-product-cross-connect">
            <input type="checkbox" checked={defaultRequiresCrossConnect} onChange={(e) => setDefaultRequiresCrossConnect(e.target.checked)} />
            Butuh Cross-Connect
          </label>
        </section>

        <section className="crm-product-form-section">
          <div className="crm-product-section-heading">
            <span className="crm-product-section-heading__icon" style={{ background: "#ecfdf5", color: "#059669" }}><ImageIcon size={17} /></span>
            <div>
              <h3 className="crm-product-section-heading__title">Gambar Produk</h3>
              <p className="crm-product-section-heading__subtitle">Tambahkan foto pendukung katalog produk atau jasa.</p>
            </div>
            <span className="crm-product-section-heading__step" aria-hidden="true">04</span>
          </div>
          <div className="crm-product-upload-wrap">
            <FileUploadField label="Gambar Produk" moduleCode="CrmSales" referenceType="product_image" currentFileId={imageFileId} accept="image/*" onUploaded={(id) => setImageFileId(id)} onRemove={() => setImageFileId(null)} />
          </div>
        </section>

        {error && <div className="crm-product-form-error">{error}</div>}

        <div className="crm-product-form-actions">
          <Button type="button" variant="secondary" onClick={onClose} className="crm-product-secondary-button">Batal</Button>
          <Button type="submit" disabled={saving} className="crm-product-primary-button">
            {saving ? "Menyimpan..." : isEdit ? "Simpan" : "Buat Produk"}
          </Button>
        </div>
      </form>
    );
    if (isEdit) {
        return (<ProductEditPopup title={`Edit: ${product.name}`} onClose={onClose}>
                {formContent}
            </ProductEditPopup>);
    }
    return (
      <div className="crm-product-ui crm-product-form-page">
        <ProductPageStyles />
        <PageHeader title="Produk & Jasa" subtitle="Master data produk dan layanan MSDC." containerClassName="px-7 pt-5 pb-2" />
        <main className="crm-product-content crm-product-form-page-content">
          <div className="crm-product-form-nav">
            <button type="button" onClick={onClose} className="crm-product-back">
              <ArrowLeft size={16} /> Kembali ke daftar Produk &amp; Jasa
            </button>
            <span className="crm-product-form-nav__tag">Form Produk Baru</span>
          </div>
          <section className="crm-product-form-intro">
            <div className="crm-product-form-intro__main">
              <span className="crm-product-form-intro__icon" aria-hidden="true"><Package size={23} strokeWidth={1.9} /></span>
              <div className="crm-product-form-intro__copy">
                <h2 className="crm-product-form-intro__title">Produk / Jasa Baru</h2>
                <p className="crm-product-form-intro__subtitle">Lengkapi identitas, harga, dan kebutuhan layanan untuk katalog MSDC.</p>
              </div>
            </div>
            <span className="crm-product-form-intro__badge">Data Produk &amp; Jasa</span>
          </section>
          {formContent}
        </main>
      </div>
    );
}
